window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cd4d2fb37fde3012"]={"versions": [{"id": "FIG-cd4d2fb37fde3012", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Deinit()</code>) zur Spezifikation des Deinitialisierungsablaufs des AUTOSAR ADC-Treibers (Mikrocontroller-Abstraktionsschicht, MCAL) im Kontext des ECU State Managers (EcuM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Lebenslinien <code>EcuM::EcuM</code> (ECU State Manager, Aufrufer) und <code>Adc::Adc</code> (ADC-Treiber-Modul, Zielkomponente). Als Schnittstellenoperation tritt der synchrone Funktionsaufruf <code>Adc_DeInit()</code> auf.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Aufrufer <code>EcuM::EcuM</code> initiiert den synchronen Aufruf <code>Adc_DeInit()</code> an <code>Adc::Adc</code>. Nach Ausführung der Deinitialisierungsroutine auf der aktiven Ausführungsüberlagerung von <code>Adc::Adc</code> erfolgt die Rückkehr der Kontrollfluss-Sequenz via Return-Nachricht <code>Adc_DeInit</code> zurück an <code>EcuM::EcuM</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Deinitialisierungssequenz dokumentiert den formalen Ablauf der Deinitialisierung des ADC-Treibers durch den EcuM. Das Diagramm enthält keine zusätzlichen textuellen Randbedingungen oder Vorbedingungen bezüglich Interrupt- und Benachrichtigungszuständen.</p>"}, {"id": "FIG-dbf58d60d312d4d6", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Deinit()</code>) zur Spezifikation des Deinitialisierungsablaufs des AUTOSAR ADC-Treibers (Mikrocontroller-Abstraktionsschicht, MCAL) im Kontext des ECU State Managers (EcuM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Lebenslinien <code>EcuM::EcuM</code> und <code>Adc::Adc</code>, jeweils explizit als <code>«module»</code> typisiert. Als Schnittstellenoperation tritt der synchrone Funktionsaufruf <code>Adc_DeInit()</code> auf.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Aufrufer <code>EcuM::EcuM</code> initiiert den synchronen Aufruf <code>Adc_DeInit()</code> an <code>Adc::Adc</code>. Nach Ausführung der Deinitialisierungsroutine auf der aktiven Ausführungsüberlagerung von <code>Adc::Adc</code> erfolgt die Rückkehr der Kontrollfluss-Sequenz via Return-Nachricht <code>Adc_DeInit</code> zurück an <code>EcuM::EcuM</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Deinitialisierung durch <code>Adc_DeInit()</code> erfordert spezifische Deinitialisierungsbedingungen:</p>\n<ul class=\"fig-list\"><li>Alle Notifications müssen deaktiviert werden.\n</li><li>Alle verwendeten Interrupts müssen deaktiviert werden.\n</li><li>Es liegt in der Verantwortung des Hardware-Designs, dass dieser Zustand nicht zu unbestimmten Aktivitäten im Mikrocontroller führt.\n</li></ul>\n<p class=\"fig-p\">Die Spezifikationsnotiz führt den Status „Proposed by TO as per SWS ADC 2.0.1“ mit der Beschreibung „ADC driver and hardware deinitialization.“ auf.</p>"}, {"id": "FIG-632c5450a0d13f9f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Deinit()</code>) zur Spezifikation des Deinitialisierungsablaufs des AUTOSAR ADC-Treibers (Mikrocontroller-Abstraktionsschicht, MCAL) im Kontext des ECU State Managers (EcuM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Lebenslinien <code>EcuM</code> und <code>Adc</code>, jeweils explizit mit dem Stereotyp <code>«module»</code> versehen. Als Schnittstellenoperation tritt der synchrone Funktionsaufruf <code>Adc_DeInit()</code> auf.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Aufrufer <code>EcuM</code> sendet den synchronen Aufruf <code>Adc_DeInit()</code> an das Modul <code>Adc</code>. Nach Durchführung der Treiber- und Hardware-Deinitialisierung kehrt der Kontrollfluss mit der Rückgabenachricht <code>Adc_DeInit()</code> zum <code>EcuM</code> zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Deinitialisierung durch <code>Adc_DeInit()</code> erfordert spezifische Deinitialisierungsbedingungen:</p>\n<ul class=\"fig-list\"><li>Alle Notifications müssen deaktiviert werden.\n</li><li>Alle verwendeten Interrupts müssen deaktiviert werden.\n</li><li>Es liegt in der Verantwortung des Hardware-Designs, dass dieser Zustand nicht zu unbestimmten Aktivitäten im Mikrocontroller führt.\n</li></ul>\n<p class=\"fig-p\">Die Spezifikationsnotiz führt den Status „Proposed by TO as per SWS ADC 2.0.1“ mit der Beschreibung „ADC driver and hardware deinitialization.“ auf.</p>"}], "trans": [{"from": "FIG-cd4d2fb37fde3012", "to": "FIG-dbf58d60d312d4d6", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp: Die Lebenslinienköpfe werden um das Stereotyp <code>«module»</code> ergänzt.\n</li><li>Kommentarfeld: Eine erläuternde Notizbox mit Status-, Beschreibungs- und Anforderungsdetails zur Deinitialisierung wird unterhalb des Sequenzverlaufs eingefügt.\n</li><li>Deinitialisierungsbedingungen: Anforderung spezifiziert, dass alle Benachrichtigungen (Notifications) und verwendeten Interrupts deaktiviert werden müssen sowie Hardware-Design-Verantwortung für unbestimmte Aktivitäten definiert.\n</li></ul>"}, {"from": "FIG-dbf58d60d312d4d6", "to": "FIG-632c5450a0d13f9f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Lebenslinien-Beschriftung: <code>EcuM::EcuM</code> wird zu <code>EcuM</code> verkürzt; <code>Adc::Adc</code> wird zu <code>Adc</code> verkürzt.\n</li><li>Rückkehr-Nachricht: Die Beschriftung des Return-Pfeils wird von <code>Adc_DeInit</code> auf <code>Adc_DeInit()</code> korrigiert (Klammern ergänzt).\n</li></ul>"}]};
